<?php
declare(strict_types=1);

namespace App\Infrastructure\Persistence;

use App\Application\Exceptions\OperationConflict;
use App\Application\Read\Page;
use App\Application\Repositories\CustomerRepository;
use PDO;

final class PdoCustomerRepository extends PdoRepository implements CustomerRepository
{
    public function customers(string $search,string $status,?string $type,?int $branchId,array $allowedBranches,int $limit,int $offset):Page
    {
        [$limit,$offset]=self::pageBounds($limit,$offset);$allowed=self::ids($allowedBranches);if($allowed===[])return new Page([],$limit,$offset,false);$where=['c.branch_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')'];$params=$allowed;$search=trim($search);if(strlen($search)>120)throw new \InvalidArgumentException('La búsqueda es demasiado larga.');
        if($search!==''){$where[]='(c.code LIKE ? OR c.legal_name LIKE ? OR c.trade_name LIKE ? OR c.tax_identifier LIKE ? OR c.email LIKE ?)';$term='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$search).'%';array_push($params,$term,$term,$term,$term,$term);}
        if($status==='active')$where[]='c.is_active=1';elseif($status==='inactive')$where[]='c.is_active=0';elseif($status!=='all')throw new \InvalidArgumentException('El estado no es válido.');if($type!==null){if(!in_array($type,['individual','business'],true))throw new \InvalidArgumentException('El tipo no es válido.');$where[]='c.customer_type=?';$params[]=$type;}if($branchId!==null){if(!in_array($branchId,$allowed,true))throw new OperationConflict('La sucursal está fuera de tu alcance.');$where[]='c.branch_id=?';$params[]=$branchId;}
        $sql='SELECT c.*,b.name branch_name,pl.name price_list_name,cc.name contact_name,(SELECT COUNT(*) FROM customer_contacts x WHERE x.customer_id=c.id) contact_count FROM customers c INNER JOIN branches b ON b.id=c.branch_id LEFT JOIN price_lists pl ON pl.id=c.price_list_id LEFT JOIN customer_contacts cc ON cc.customer_id=c.id AND cc.is_primary=1 WHERE '.implode(' AND ',$where).' ORDER BY c.legal_name,c.id LIMIT ? OFFSET ?';$st=$this->pdo()->prepare($sql);$i=1;foreach($params as$v)$st->bindValue($i++,$v,is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR);$st->bindValue($i++,$limit+1,PDO::PARAM_INT);$st->bindValue($i,$offset,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll();$more=count($rows)>$limit;if($more)array_pop($rows);return new Page($rows,$limit,$offset,$more);
    }
    public function customer(int$id,array$allowedBranches,bool$lock=false):?array{$allowed=self::ids($allowedBranches);if($allowed===[])return null;$sql='SELECT c.*,b.name branch_name,pl.name price_list_name,cc.name contact_name,cc.role contact_role,cc.phone contact_phone,cc.email contact_email,ca.address_type,ca.line1 address_line1,ca.line2 address_line2,ca.city,ca.state_name,ca.postal_code FROM customers c INNER JOIN branches b ON b.id=c.branch_id LEFT JOIN price_lists pl ON pl.id=c.price_list_id LEFT JOIN customer_contacts cc ON cc.customer_id=c.id AND cc.is_primary=1 LEFT JOIN customer_addresses ca ON ca.customer_id=c.id AND ca.is_primary=1 WHERE c.id=? AND c.branch_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')'.($lock?' FOR UPDATE':'');$st=$this->pdo()->prepare($sql);$st->execute(array_merge([self::id($id)],$allowed));$row=$st->fetch();return$row===false?null:$row;}
    public function create(array$d):int{return$this->safely(function()use($d):int{$st=$this->pdo()->prepare('INSERT INTO customers(branch_id,price_list_id,code,customer_type,legal_name,trade_name,tax_identifier,email,phone,alternate_phone,notes,is_active,lock_version,created_by,updated_by) VALUES(:branch_id,:price_list_id,:code,:customer_type,:legal_name,:trade_name,:tax_identifier,:email,:phone,:alternate_phone,:notes,1,1,:actor,:actor)');$st->execute($d);return$this->insertedId();},'No fue posible registrar el cliente.');}
    public function update(int$id,int$version,array$d):void{$d['id']=self::id($id);$d['version']=$version;$st=$this->pdo()->prepare('UPDATE customers SET branch_id=:branch_id,price_list_id=:price_list_id,code=:code,customer_type=:customer_type,legal_name=:legal_name,trade_name=:trade_name,tax_identifier=:tax_identifier,email=:email,phone=:phone,alternate_phone=:alternate_phone,notes=:notes,updated_by=:actor,lock_version=lock_version+1 WHERE id=:id AND lock_version=:version');try{$st->execute($d);}catch(\PDOException$e){if(($e->errorInfo[0]??'')==='23000')throw new OperationConflict('Ya existe un cliente con ese código o identificador fiscal.');throw$e;}if($st->rowCount()!==1)throw new OperationConflict('El cliente cambió en otra sesión. Recarga la página.');}
    public function setActive(int$id,int$version,bool$active,int$actorId):void{$st=$this->pdo()->prepare('UPDATE customers SET is_active=:active,updated_by=:actor,lock_version=lock_version+1 WHERE id=:id AND lock_version=:version');$st->execute(['active'=>$active?1:0,'actor'=>self::id($actorId),'id'=>self::id($id),'version'=>$version]);if($st->rowCount()!==1)throw new OperationConflict('El cliente cambió en otra sesión. Recarga la página.');}
    public function savePrimaryContact(int$id,?array$c):void{$id=self::id($id);if($c===null){$this->pdo()->prepare('DELETE FROM customer_contacts WHERE customer_id=? AND is_primary=1')->execute([$id]);return;}$c['customer_id']=$id;$this->pdo()->prepare('INSERT INTO customer_contacts(customer_id,name,role,phone,email,is_primary) VALUES(:customer_id,:name,:role,:phone,:email,1) ON DUPLICATE KEY UPDATE name=VALUES(name),role=VALUES(role),phone=VALUES(phone),email=VALUES(email)')->execute($c);}
    public function savePrimaryAddress(int$id,?array$a):void{$id=self::id($id);if($a===null){$this->pdo()->prepare('DELETE FROM customer_addresses WHERE customer_id=? AND is_primary=1')->execute([$id]);return;}$a['customer_id']=$id;$this->pdo()->prepare('INSERT INTO customer_addresses(customer_id,address_type,line1,line2,city,state_name,postal_code,is_primary) VALUES(:customer_id,:address_type,:line1,:line2,:city,:state_name,:postal_code,1) ON DUPLICATE KEY UPDATE address_type=VALUES(address_type),line1=VALUES(line1),line2=VALUES(line2),city=VALUES(city),state_name=VALUES(state_name),postal_code=VALUES(postal_code)')->execute($a);}
    public function possibleDuplicates(array$d,?int$excludeId=null):array{$parts=[];$p=[];foreach(['email','phone']as$field)if($d[$field]!==null){$parts[]="c.$field=?";$p[]=$d[$field];}if($parts===[])return[];$sql='SELECT c.id,c.code,c.legal_name,b.name branch_name FROM customers c INNER JOIN branches b ON b.id=c.branch_id WHERE ('.implode(' OR ',$parts).')'.($excludeId!==null?' AND c.id<>?':'').' ORDER BY c.id LIMIT 5';if($excludeId!==null)$p[]=self::id($excludeId);$st=$this->pdo()->prepare($sql);$st->execute($p);return$st->fetchAll();}
    public function branches(array$allowed):array{$allowed=self::ids($allowed);if($allowed===[])return[];$st=$this->pdo()->prepare('SELECT id,code,name FROM branches WHERE is_active=1 AND id IN ('.implode(',',array_fill(0,count($allowed),'?')).') ORDER BY name,id');$st->execute($allowed);return$st->fetchAll();}
    public function priceLists():array{return$this->pdo()->query('SELECT id,code,name FROM price_lists WHERE is_active=1 ORDER BY name,id LIMIT 1000')->fetchAll();}
    private static function ids(array$ids):array{$ids=array_values(array_unique(array_filter(array_map('intval',$ids),static fn(int$id):bool=>$id>0)));sort($ids);return$ids;}
}
